import React, { Component } from 'react';
import moment from 'moment';
import { requestHeaderDELETEWithAuth, requestHeaderGETWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import Table from 'react-bootstrap/Table';
import { CButton, CCard, CCardBody, CCol, CRow } from '@coreui/react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { BACKEND_TYPING_SPEED_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "TypingSessionList.js";

const initialState = {
	isLoaded: false,
	loadingModalVisible: false,
	loadingModalState: 0,
	failureModalVisible: false,
	sessionListData: [],
	statsData: null,
	statsError: false
};

class TypingSessionList extends Component {

	constructor(props) {
		super(props);
		this.state = JSON.parse(JSON.stringify(initialState));
	}

	resetStateToDefault() {
		this.setState(JSON.parse(JSON.stringify(initialState)));
	}

	componentDidMount() {
		document.title = "Satanlabs - Typing Speed Sessions";
		this.fetchSessionList();
		this.fetchStats();
	}

	fetchSessionList() {
		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/list?offset=0';
		const userData = getUserDataFromLocalStorage();

		fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_LIST", "result", result);
				if(result.code === 1001) {
					//success
					this.setState({
						isLoaded: true,
						sessionListData: result.data
					});
				} else {
					//something horrible happened
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_LIST", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	fetchStats() {
		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/stats';
		const userData = getUserDataFromLocalStorage();

		fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_STATS", "result", result);
				if(result.code === 1001) {
					this.setState({
						statsData: result.data,
						statsError: false
					});
				} else {
					this.setState({
						statsError: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_STATS", "error", error);
				this.setState({
					statsError: true
				});
			}
		);
	}

	reloadData() {
		this.resetStateToDefault();
		this.fetchSessionList();
		this.fetchStats();
	}

	markSessionDeleted(id) {
		if(window.confirm("Surely want to DELETE typing session id = " + id + " ?")) {
			this.callDeletionApi(id);
		}
	}

	callDeletionApi(id) {
		this.setState({
			loadingModalVisible: true,
			loadingModalState: 0,
		});

		const API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + "/" + id;
		const userData = getUserDataFromLocalStorage();
		fetch(API_URL, requestHeaderDELETEWithAuth(null, userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_DELETE", "result", result);
				if(result.code === 1001) {
					//success
					this.setState({
						loadingModalState: 1
					});

					setTimeout(() => {
						this.setState({
							loadingModalVisible: false,
							loadingModalState: 0,
						});
						this.reloadData();
					}, 500);
				} else {
					//something horrible happened
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_DELETE", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	renderStatsCards() {
		const { statsData, statsError } = this.state;

		const cardStyle = {
			textAlign: 'center',
			padding: '16px'
		};

		const valueStyle = {
			fontSize: '2rem',
			fontWeight: 'bold',
			margin: '8px 0'
		};

		const labelStyle = {
			fontSize: '0.9rem',
			color: '#6c757d',
			margin: 0
		};

		if(statsError) {
			return (
				<CRow className="mb-4">
					<CCol sm="3">
						<CCard>
							<CCardBody style={cardStyle}>
								<p style={labelStyle}>Best WPM</p>
								<p style={{...valueStyle, color: '#dc3545'}}>--</p>
								<small style={{color: '#dc3545'}}>Error loading</small>
							</CCardBody>
						</CCard>
					</CCol>
					<CCol sm="3">
						<CCard>
							<CCardBody style={cardStyle}>
								<p style={labelStyle}>Average WPM</p>
								<p style={{...valueStyle, color: '#dc3545'}}>--</p>
								<small style={{color: '#dc3545'}}>Error loading</small>
							</CCardBody>
						</CCard>
					</CCol>
					<CCol sm="3">
						<CCard>
							<CCardBody style={cardStyle}>
								<p style={labelStyle}>Average Accuracy</p>
								<p style={{...valueStyle, color: '#dc3545'}}>--</p>
								<small style={{color: '#dc3545'}}>Error loading</small>
							</CCardBody>
						</CCard>
					</CCol>
					<CCol sm="3">
						<CCard>
							<CCardBody style={cardStyle}>
								<p style={labelStyle}>Total Sessions</p>
								<p style={{...valueStyle, color: '#dc3545'}}>--</p>
								<small style={{color: '#dc3545'}}>Error loading</small>
							</CCardBody>
						</CCard>
					</CCol>
				</CRow>
			);
		}

		if(!statsData) {
			return null;
		}

		return (
			<CRow className="mb-4">
				<CCol sm="3">
					<CCard>
						<CCardBody style={cardStyle}>
							<p style={labelStyle}>Best WPM</p>
							<p style={{...valueStyle, color: '#28a745'}}>{statsData.highestWpm != null ? statsData.highestWpm : '--'}</p>
						</CCardBody>
					</CCard>
				</CCol>
				<CCol sm="3">
					<CCard>
						<CCardBody style={cardStyle}>
							<p style={labelStyle}>Average WPM</p>
							<p style={{...valueStyle, color: '#007bff'}}>{statsData.averageWpm != null ? statsData.averageWpm.toFixed(1) : '--'}</p>
						</CCardBody>
					</CCard>
				</CCol>
				<CCol sm="3">
					<CCard>
						<CCardBody style={cardStyle}>
							<p style={labelStyle}>Average Accuracy</p>
							<p style={{...valueStyle, color: '#17a2b8'}}>{statsData.averageAccuracy != null ? statsData.averageAccuracy.toFixed(1) + '%' : '--'}</p>
						</CCardBody>
					</CCard>
				</CCol>
				<CCol sm="3">
					<CCard>
						<CCardBody style={cardStyle}>
							<p style={labelStyle}>Total Sessions</p>
							<p style={{...valueStyle, color: '#6f42c1'}}>{statsData.totalSessions != null ? statsData.totalSessions : '--'}</p>
						</CCardBody>
					</CCard>
				</CCol>
			</CRow>
		);
	}

	render() {
		Logger(FILE_NAME, "render", "", "this.state", this.state);

		return (
			this.state.isLoaded ?
			<div>
				{/* Quick links */}
				<div style={{ display: 'flex', gap: '16px', marginBottom: '24px', flexWrap: 'wrap' }}>
					<a href="#/typing-speed/save" style={{ textDecoration: 'none', flex: 1, minWidth: '200px' }}>
						<div style={{
							padding: '24px',
							backgroundColor: '#d4edda',
							borderRadius: '8px',
							border: '1px solid #c3e6cb',
							textAlign: 'center',
							cursor: 'pointer',
							transition: 'transform 0.2s',
						}}>
							<h3 style={{ margin: 0, color: '#155724' }}>⌨️ Save Session</h3>
							<p style={{ margin: '8px 0 0', color: '#155724', opacity: 0.8 }}>Record a new typing session</p>
						</div>
					</a>
					<a href="#/typing-speed/source" style={{ textDecoration: 'none', flex: 1, minWidth: '200px' }}>
						<div style={{
							padding: '24px',
							backgroundColor: '#cce5ff',
							borderRadius: '8px',
							border: '1px solid #b8daff',
							textAlign: 'center',
							cursor: 'pointer',
							transition: 'transform 0.2s',
						}}>
							<h3 style={{ margin: 0, color: '#004085' }}>🌐 Source Websites</h3>
							<p style={{ margin: '8px 0 0', color: '#004085', opacity: 0.8 }}>Manage typing test websites</p>
						</div>
					</a>
					<a href="#/typing-speed/graph" style={{ textDecoration: 'none', flex: 1, minWidth: '200px' }}>
						<div style={{
							padding: '24px',
							backgroundColor: '#fff3cd',
							borderRadius: '8px',
							border: '1px solid #ffc107',
							textAlign: 'center',
							cursor: 'pointer',
							transition: 'transform 0.2s',
						}}>
							<h3 style={{ margin: 0, color: '#856404' }}>📈 Speed Graph</h3>
							<p style={{ margin: '8px 0 0', color: '#856404', opacity: 0.8 }}>View typing speed trends</p>
						</div>
					</a>
				</div>

				{/* Stats Dashboard */}
				{this.renderStatsCards()}

				<h2>Typing Sessions :</h2>
				<CButton color="success" className="px-4" onClick={() => this.reloadData()}>reloadData</CButton>
				<br /><br />
				<Table striped bordered hover color='success' style={{'width':'100%'}}>
					<thead>
						<tr>
						<th>#</th>
						<th>WPM</th>
						<th>CPM</th>
						<th>Accuracy</th>
						<th>Extra Notes</th>
						<th>createdOn</th>
						<th>Actions</th>
						</tr>
					</thead>
					<tbody>
						{
							this.state.sessionListData.map(
								session =>
								<tr key={"typing_session_item_id_" + session.id}>
									<td>{session.id}</td>
									<td>{session.wpm}</td>
									<td>{session.cpm}</td>
									<td>{session.accuracy}%</td>
									<td>{session.extraNotes == null ? "N/A" : session.extraNotes}</td>
									<td>{session.createdOn} ~ {moment(session.createdOn).format('YYYY/MM/DD HH:mm ddd')}</td>
									<td>
										<CButton color="danger" className="px-4" onClick={() => this.markSessionDeleted(session.id)}>DELETE</CButton>
									</td>
								</tr>
							)
						}
					</tbody>
				</Table>
				<StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
				<FailureModal visible={this.state.failureModalVisible} />
			</div>
			 : <Loading />
		);
	}

}

export default TypingSessionList;
